mapper.select:
SELECT T1.employeeId, CONCAT(SUBSTRING(T1.salaryMonth,1,4),"年",SUBSTRING(T1.salaryMonth,5,7),"月") AS salaryMonth, FORMAT(T1.salary,0) AS salary, T1.workhours, FORMAT(T1.disabledGeneration,0) AS disabledGeneration, FORMAT(T1.cost,0) AS cost, FORMAT(T1.actualSalary,0) AS actualSalary, T2.name as employeeName FROM cms_salary_detail T1 left join cms_employee T2 on T1.employeeId = T2.employeeId
and T1.employeeId = #{employeeId}
and T1.salaryMonth = #{salaryMonth}
order by T1.employeeId asc, T1.salaryMonth DESC
